--- 设置单击回调函数
---@param cb fun():void
function CommonTabToggleLeftCell:SetCallBack(cb)
    self.__callback = cb
end


function CommonTabToggleLeftCell:Awake()
    self.qualityPop = self.controller.transform:Find("AnimRoot/QuantityPop")
    self.levelTrans = self.AnimRoot.transform:Find("Unlock/Level")
    self.iconTxtNumTrans = self.ImgIcon.transform.parent:Find("TxtNum")
    self.shadowComp = self.Text.transform:GetComponent(typeof(ShadowType))
    if not isNull(self.ImgIcon) then
        local goImage = self.ImgIcon.transform:GetComponent(typeof(ImageAlterable))
        if not goImage then
            goImage = self.ImgIcon.transform:GetComponent(typeof(RawImageAlterable))
        end
        if goImage then
            goImage.IsAutoAlpha = true
        end
    end
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            self.__callback()
        end
    end
end


