---显示背包上限的信息
---@param text string
function CommonTabToggleLeftCell:FreshPacketText(text)
    if not isNull(self.qualityPop) then
        CfUtils.SetActive(self.qualityPop, true)
        CfUtils.FillText(self.qualityPop.transform:Find("TxtNum"), text)
    end
end


---@param visibility boolean
---@param level integer
---@param iconPath string
function CommonTabToggleLeftCell:SetAreaLevel(visibility, level, iconPath)
    local isVisibility = checkBool(visibility)
    if not isNull(self.levelTrans) then
        CfUtils.SetActive(self.levelTrans, isVisibility)
        CfUtils.SetActive(self.ImgIcon.transform.parent, isVisibility)
        if isVisibility then
            CfUtils.FillText(self.levelTrans:Find("TextNumber"), tostring(level))
            if iconPath then
                CfUtils.FillImage(self.ImgIcon, iconPath)
            end
        end
        if self.ImgLock then
            CfUtils.SetActive(self.ImgLock, not isVisibility)--特殊显示的图片
        end
    end
end

function CommonTabToggleLeftCell:SetAreaNum(isUnlock,Text,isToMax,isHaveReward)
    local isVisible = checkBool(isUnlock)
    if isVisible then
        CfUtils.SetActive(self.SelectText, not isToMax)
        --CfUtils.SetActive(self.ImgReward, isHaveReward)
        CfUtils.SetActive(self.CompleteTxtNode, isToMax)
        if not isToMax then
            CfUtils.FillText(self.TextNumber,Text)
        end
    else
        CfUtils.SetActive(self.SelectText, false)
        --CfUtils.SetActive(self.ImgReward, false)
        CfUtils.SetActive(self.CompleteTxtNode, false)
    end
end

---@param visibility boolean
function CommonTabToggleLeftCell:SetQuantityVisible(visibility)
    if not isNull(self.qualityPop) then
        CfUtils.SetActive(self.qualityPop, visibility == true)
    end
end


---@param data table
function CommonTabToggleLeftCell:FreshBaseUI(data)
    if not isNull(self.qualityPop) then
        CfUtils.SetActive(self.qualityPop, false)
    end

    CfUtils.FillText(self.Text, data.text)

    -- selectImgPath 太长了，而且词不达意，所以新增 iconPath 字段来达到相同作用。但是不要两者一起使用!!
    if data.iconPath == nil then
        data.iconPath = data.selectImgPath
    end
    CfUtils.SetActive(self.ImgIcon.transform.parent, not isNull(data.iconPath))--状态的图片
    if not isNull(data.iconPath) then
        CfUtils.FillImage(self.ImgIcon, data.iconPath)
    end

    if not isNull(data.lock) then
        if self.ImgLock then
            CfUtils.SetActive(self.ImgLock, data.lock)--特殊显示的图片
            CfUtils.SetActive(self.ImgIcon.transform.parent, false)
        end
    else
        CfUtils.SetActive(self.ImgLock, false)--特殊显示的图片
    end
end


---@param isSelected boolean
---@param data table @ { textDefStatus : integer, imgIconDefStatus : integer, isHideShadow : boolean}
function CommonTabToggleLeftCell:FreshSelectStatus(isSelected, data)
    CfUtils.SetActive(self.Image, isSelected)
    --CfUtils.SetActive(self.SelectText, isSelected)
    CfUtils.SetUISwitchText(self.TextNumber, isSelected and SwitchTextStatusEnum.Selected or (checkTable(data).textDefStatus or SwitchTextStatusEnum.Default))
    CfUtils.SetUISwitchText(self.Text, isSelected and SwitchTextStatusEnum.Selected or (checkTable(data).textDefStatus or SwitchTextStatusEnum.Default))
    CfUtils.SetUISwitchImage(self.ImgIcon, isSelected and SwitchImageStatusIcon.Selected or (checkTable(data).imgIconDefStatus or SwitchImageStatusIcon.Unselect))
    if not isNull(data) and data.isHideShadow ~= nil then
        if not isNull(self.shadowComp) then
            self.shadowComp.enabled = not data.isHideShadow
        end
    end
    self.isSelected = isSelected
    CfUtils.PlayAnimation(self.AnimRoot, isSelected and "CommonTabToggleLeftGo" or "CommonTabToggleLeftDefault")
end

function CommonTabToggleLeftCell:FreshIconTxtNum(num, isSelected)
    local isShow = num ~= nil
    CfUtils.SetActive(self.iconTxtNumTrans, isShow)
    if isShow then
        CfUtils.FillText(self.iconTxtNumTrans, num)
        
    end
    CfUtils.SetUISwitchText(self.iconTxtNumTrans, isSelected and SwitchTextStatusEnum.Selected or SwitchTextStatusEnum.Default)
    
end

function CommonTabToggleLeftCell:OnEnable()
    -- 修复刚刚初始化时，动画还未播放完毕，某个父容器就被关闭了，导致状态被停在了默认状态
    -- 所以在启用时，重新播放动画，以回复正常显示状态
    local isSelected = self.isSelected
    CfUtils.PlayAnimation(self.AnimRoot, isSelected and "CommonTabToggleLeftGo" or "CommonTabToggleLeftDefault")
end


---@param isShowRedPoint boolean
function CommonTabToggleLeftCell:FreshRedPointStatus(isShowRedPoint)
    CfUtils.SetActive(self.redPoint, isShowRedPoint == true)
end

function CommonTabToggleLeftCell:GetRedPoint()
    return self.redPoint
end


return CommonTabToggleLeftCell
